/// The embedded details are the retained bytes, and every subset decodes
/// through the production models.
@MainActor
final class SoccerRetainedAdapter10868Tests: XCTestCase {
    private typealias F = SoccerRetained10868

    func testTheEmbeddedDetailsAreTheRetainedBytes() {
        XCTAssertEqual(F.sha256(F.hullDetail), "05aba8d16e2ac82c2ba7e1a64471918c96e76e93821d893c324ecfaa989f0eab")
        XCTAssertEqual(F.sha256(F.liveDetail), "e14790d9ec05a49f4b241cc8e9cd3cd1290f14a14cfe6eeb52053a2b94de4645")
        XCTAssertEqual(F.sha256(F.finalDetail), "2a365c2f197d33eb75d10c6acc65532f1b3afe7bb0e7361dd56dfae0bf74fa90")
    }

    func testEverySubsetDecodesThroughTheProductionModels() throws {
        let hull = try F.detail(F.hullDetail)
        XCTAssertEqual(hull.id, 15311089)
        XCTAssertEqual(hull.status, "scheduled")
        let live = try F.detail(F.liveDetail)
        XCTAssertEqual(live.status, "live")
        XCTAssertEqual(live.homeScore, 4)
        let final = try F.detail(F.finalDetail)
        XCTAssertTrue(EventState.isFinished(final.status))
        XCTAssertEqual(final.homeScore, 5)

        XCTAssertEqual(try F.history(F.hullHistory).aggregateLine?.count, 7)
        XCTAssertEqual(try F.history(F.liveHistory).scoreHistory?.count, 5)
        XCTAssertEqual(try F.history(F.finalHistory).aggregateLine?.count, 27)

        let liveMarkets = try F.markets(F.liveMarkets)
        XCTAssertEqual(liveMarkets.other?.count, 14)
        XCTAssertEqual(liveMarkets.totals?.count, 4)
        // The matrix decoded every kept question: none was dropped as unreadable.
        XCTAssertEqual(liveMarkets.gameQuestionMatrix?.questions.count, 9)
        XCTAssertEqual(liveMarkets.gameQuestionMatrix?.droppedQuestions, 0)
        XCTAssertEqual(try F.markets(F.hullMarkets).gameQuestionMatrix?.questions.count, 5)
        XCTAssertEqual(try F.markets(F.finalMarkets).gameQuestionMatrix?.questions.count, 4)
    }
}
